import copy, re, zipfile, shutil, sys, difflib, importlib.util
from lxml import etree
WNS="http://schemas.openxmlformats.org/wordprocessingml/2006/main"
W="{%s}"%WNS
XML_SPACE="{http://www.w3.org/XML/1998/namespace}space"
AUTHOR="Ledgerwood & Pratt LLP"; DATE="2025-03-14T00:00:00Z"
rid=[1000]
def nid():
    rid[0]+=1; return str(rid[0])
def el(tag, **attrs):
    e=etree.Element(W+tag)
    for k,v in attrs.items(): e.set(W+k, v)
    return e
def mk_run(rpr, text, deleted=False):
    r=el("r")
    if rpr is not None: r.append(copy.deepcopy(rpr))
    t=el("delText" if deleted else "t"); t.text=text; t.set(XML_SPACE,"preserve"); r.append(t)
    return r
def ins_wrap(runs):
    w=el("ins", id=nid(), author=AUTHOR, date=DATE)
    for r in runs: w.append(r)
    return w
def del_wrap(runs):
    w=el("del", id=nid(), author=AUTHOR, date=DATE)
    for r in runs: w.append(r)
    return w
def is_bold(rpr):
    return rpr is not None and rpr.find(W+"b") is not None
def base_rpr(p):
    for r in p.findall(W+"r"):
        rp=r.find(W+"rPr")
        if not is_bold(rp): return rp
    rp=copy.deepcopy(p.find(W+"r").find(W+"rPr"))
    for tag in ("b","u","i"):
        x=rp.find(W+tag)
        if x is not None: rp.remove(x)
    return rp
def styled(base, bold, italic=False):
    rp=copy.deepcopy(base)
    for tag in ("b","u","i"):
        x=rp.find(W+tag)
        if x is not None: rp.remove(x)
    if bold or italic:
        # insert after rFonts
        idx=1 if rp.find(W+"rFonts") is not None else 0
        if italic: rp.insert(idx, el("i"))
        if bold: rp.insert(idx, el("b"))
    return rp
def parse_marked(s):
    chars=[];flags=[];b=False;it=False;i=0
    while i<len(s):
        if s.startswith("**",i): b=not b;i+=2;continue
        if s.startswith("__",i): it=not it;i+=2;continue
        chars.append(s[i]);flags.append((b,it));i+=1
    return "".join(chars),flags
def orig_chars(p):
    chars=[];rprs=[]
    for r in p.findall(W+"r"):
        rp=r.find(W+"rPr")
        for t in r.findall(W+"t"):
            for c in (t.text or ""):
                chars.append(c);rprs.append(rp)
    return "".join(chars),rprs
def group(text, rprs):
    out=[];cur=None;buf=""
    for c,rp in zip(text,rprs):
        if rp is not cur and buf:
            out.append((cur,buf));buf=""
        cur=rp;buf+=c
    if buf: out.append((cur,buf))
    return out
def tok(s): return re.findall(r"\s+|[^\s]+", s)
def clear_runs(p):
    for ch in list(p):
        if ch.tag!=W+"pPr": p.remove(ch)
def revise_para(p, edits):
    old,rprs=orig_chars(p)
    # build new text with flags
    base=base_rpr(p)
    new_chars=list(old); new_rp=list(rprs)  # rp None means inserted -> use flags
    new_flags=[None]*len(old)
    cur_text=old
    for (o,n) in edits:
        if o=="__FULL__":
            nt,nf=parse_marked(n); new_chars=list(nt); new_rp=[None]*len(nt); new_flags=nf; continue
        s="".join(new_chars)
        cnt=s.count(o)
        if cnt!=1: raise SystemExit("edit anchor count %d: %r"%(cnt,o[:80]))
        k=s.index(o)
        nt,nf=parse_marked(n)
        new_chars[k:k+len(o)]=list(nt); new_rp[k:k+len(o)]=[None]*len(nt); new_flags[k:k+len(o)]=nf
    new="".join(new_chars)
    a=tok(old); b=tok(new)
    sm=difflib.SequenceMatcher(None,a,b,autojunk=False)
    # char offsets
    ao=[0];[ao.append(ao[-1]+len(x)) for x in a]
    bo=[0];[bo.append(bo[-1]+len(x)) for x in b]
    clear_runs(p)
    for op,i1,i2,j1,j2 in sm.get_opcodes():
        A=slice(ao[i1],ao[i2]); B=slice(bo[j1],bo[j2])
        if op=="equal":
            for rp,t in group(old[A],rprs[A]): p.append(mk_run(rp,t))
        else:
            if i2>i1:
                p.append(del_wrap([mk_run(rp,t,True) for rp,t in group(old[A],rprs[A])]))
            if j2>j1:
                seg=new[B]; fl=new_flags[B]; rps=new_rp[B]
                # inserted chars: use flags if None rp else original rp
                keyed=[]
                for c,f,rp in zip(seg,fl,rps):
                    if f is None: f=(is_bold(rp),False)
                    keyed.append((c,f))
                runs=[];buf="";cf=None
                for c,f in keyed:
                    if f!=cf and buf: runs.append(mk_run(styled(base,*cf),buf));buf=""
                    cf=f;buf+=c
                if buf: runs.append(mk_run(styled(base,*cf),buf))
                p.append(ins_wrap(runs))
def delete_para(p):
    old,rprs=orig_chars(p)
    clear_runs(p)
    p.append(del_wrap([mk_run(rp,t,True) for rp,t in group(old,rprs)]))
    ppr=p.find(W+"pPr"); rp=ppr.find(W+"rPr")
    if rp is None: rp=el("rPr"); ppr.append(rp)
    rp.append(el("del", id=nid(), author=AUTHOR, date=DATE))
def new_para(template, text):
    p=el("p"); ppr=copy.deepcopy(template.find(W+"pPr"))
    for x in ppr.findall(W+"keepNext"): ppr.remove(x)
    rp=ppr.find(W+"rPr")
    if rp is None: rp=el("rPr"); ppr.append(rp)
    rp.append(el("ins", id=nid(), author=AUTHOR, date=DATE))
    p.append(ppr)
    base=base_rpr(template)
    nt,nf=parse_marked(text)
    runs=[];buf="";cf=None
    for c,f in zip(nt,nf):
        if f!=cf and buf: runs.append(mk_run(styled(base,*cf),buf));buf=""
        cf=f;buf+=c
    if buf: runs.append(mk_run(styled(base,*cf),buf))
    p.append(ins_wrap(runs))
    return p
cid=[-1]
def add_comment(p, comments_root, text):
    cid[0]+=1; i=str(cid[0])
    ppr=p.find(W+"pPr")
    pos=1 if ppr is not None else 0
    p.insert(pos, el("commentRangeStart", id=i))
    p.append(el("commentRangeEnd", id=i))
    r=el("r"); rp=el("rPr"); sz=el("sz",val="16"); rp.append(sz); r.append(rp); r.append(el("commentReference", id=i)); p.append(r)
    c=el("comment", id=i, author=AUTHOR, date=DATE, initials="L&P")
    for k,para in enumerate(text.split("\n")):
        cp=el("p"); cr=el("r"); crp=el("rPr"); crp.append(el("sz",val="18")); cr.append(crp)
        t=el("t"); t.text=para; t.set(XML_SPACE,"preserve"); cr.append(t); cp.append(cr); c.append(cp)
    comments_root.append(c)
def run(src, out, spec):
    tmp="/workspace/work/build"; shutil.rmtree(tmp,ignore_errors=True)
    zipfile.ZipFile(src).extractall(tmp)
    tree=etree.parse(tmp+"/word/document.xml"); body=tree.getroot().find(W+"body")
    ps=body.findall(W+"p")
    croot=etree.Element(W+"comments", nsmap={"w":WNS})
    for idx,edits in spec.EDITS.items(): revise_para(ps[idx],edits)
    for idx in spec.DELETE: delete_para(ps[idx])
    newmap={}
    for idx,items in spec.INSERT_AFTER.items():
        anchor=ps[idx]
        for (tmpl,text) in items:
            np_=new_para(ps[tmpl],text); anchor.addnext(np_); anchor=np_
            newmap.setdefault(idx,[]).append(np_)
    for key,text in spec.COMMENTS:
        if isinstance(key,tuple): target=newmap[key[0]][key[1]]
        else: target=ps[key]
        add_comment(target,croot,text)
    tree.write(tmp+"/word/document.xml",xml_declaration=True,encoding="UTF-8",standalone=True)
    etree.ElementTree(croot).write(tmp+"/word/comments.xml",xml_declaration=True,encoding="UTF-8",standalone=True)
    rels=open(tmp+"/word/_rels/document.xml.rels").read()
    rels=rels.replace("</Relationships>",'<Relationship Id="rId99" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/comments" Target="comments.xml"/></Relationships>')
    open(tmp+"/word/_rels/document.xml.rels","w").write(rels)
    ct=open(tmp+"/[Content_Types].xml").read()
    ct=ct.replace("</Types>",'<Override PartName="/word/comments.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml"/></Types>')
    open(tmp+"/[Content_Types].xml","w").write(ct)
    # footer: mark draft label
    import os
    zf=zipfile.ZipFile(out,"w",zipfile.ZIP_DEFLATED)
    src_z=zipfile.ZipFile(src); names=src_z.namelist()
    first=["[Content_Types].xml"]+[n for n in names if n!="[Content_Types].xml"]+["word/comments.xml"]
    for n in first: zf.write(os.path.join(tmp,n),n)
    zf.close()
if __name__=="__main__":
    sp=importlib.util.spec_from_file_location("spec",sys.argv[3]); spec=importlib.util.module_from_spec(sp); sp.loader.exec_module(spec)
    run(sys.argv[1],sys.argv[2],spec)
